 scrollbar-width: thin;
 scrollbar-color: rgb(71 85 105) transparent;
 }

 .erp-skip-link {
 position: fixed;
 top: .5rem;
 right: .5rem;
 z-index: 100;
 transform: translateY(-150%);
 border-radius: .5rem;
 background: rgb(37 99 235);
 padding: .65rem 1rem;
 color: white;
 font-size: .75rem;
 font-weight: 700;
 transition: transform .15s ease;
 }

 .erp-skip-link:focus {
 transform: translateY(0);
 }

 .erp-nav {
 display: flex;
 flex-direction: column;
 gap: .25rem;
 }

 .erp-nav-link {
 position: relative;
 display: flex;
 min-height: 2.5rem;
 align-items: center;
 gap: .7rem;
 border-radius: .55rem;
 padding: .55rem .7rem;
 color: rgb(203 213 225);
 font-size: .78rem;
 font-weight: 500;
 transition: color .15s ease, background-color .15s ease, transform .15s ease;
 }

 .erp-nav-link:hover {
 background: rgb(255 255 255 / .08);
 color: white;
 }

 .erp-nav-link.is-active {
 background: rgb(29 78 216);
 color: white;
 font-weight: 600;
 box-shadow: 0 6px 16px rgb(2 6 23 / .22);
 }

 .erp-nav-link.is-active::after {
 position: absolute;
 inset-block: .55rem;
 right: -.75rem;
 width: 3px;
 border-radius: 99px 0 0 99px;
 background: rgb(147 197 253);
 content: "";
 }

 .erp-nav-link.is-unavailable {
 cursor: default;
 color: rgb(100 116 139);
 }

 .erp-nav-link>svg {
 width: 1.1rem;
 height: 1.1rem;
 flex: 0 0 1.1rem;
 fill: none;
 stroke: currentColor;
 stroke-linecap: round;
 stroke-linejoin: round;
 stroke-width: 1.7;
 }

 .erp-nav-group {
 margin-top: .35rem;
 border-top: 1px solid rgb(255 255 255 / .055);
 padding-top: .35rem;
 }

 .erp-nav-group>summary {
 display: flex;
 min-height: 1.9rem;
 cursor: pointer;
 list-style: none;
 align-items: center;
 justify-content: space-between;
 padding: .25rem .7rem;
 color: rgb(148 163 184);
 font-size: .64rem;
 font-weight: 600;
 letter-spacing: .025em;
 }

 .erp-nav-group>summary::-webkit-details-marker {
 display: none;
 }

 .erp-nav-group>summary svg {
 width: .9rem;
 height: .9rem;
 fill: none;
 stroke: currentColor;
 stroke-width: 1.8;
 transition: transform .15s ease;
 }

 .erp-nav-group:not([open])>summary svg {
 transform: rotate(90deg);
 }

 .erp-nav-group>summary:hover {
 color: rgb(226 232 240);
 }

 .erp-nav-group__items {
 display: grid;
 gap: .1rem;
 border-right: 1px solid rgb(148 163 184 / .14);
 margin-right: .7rem;
 padding-right: .35rem;
 }

 .erp-page-header {
 display: flex;
 align-items: flex-end;
 justify-content: space-between;
 gap: 1rem;
 min-height: 4.5rem;
 }

 .erp-page-header__copy {
 min-width: 0;
 }

 .erp-page-header__action:focus-visible {
 outline-color: rgb(30 64 175);
 outline-offset: 3px;
 }

 .erp-required {
 margin-right: .2rem;
 color: rgb(220 38 38);
 font-weight: 700;
 }

 .erp-form-field--invalid label {
 color: rgb(153 27 27);
 }

 .erp-form-field--invalid :where(input,
 select,
 textarea) {
 border-color: rgb(248 113 113) !important;
 background-color: rgb(254 242 242 / .5);
 }

 .erp-field-help {
 line-height: 1.6;
 }

 .erp-field-error {
 display: flex;
 align-items: center;
 gap: .3rem;
 font-size: .75rem;
 font-weight: 500;
 }

 .erp-field-error::before {
 display: grid;
 width: 1rem;
 height: 1rem;
 place-items: center;
 border-radius: 50%;
 background: rgb(254 226 226);
 content: "!";
 font-size: .65rem;
 font-weight: 700;
 }

 .erp-message {
 display: flex;
 align-items: flex-start;
 gap: .65rem;
 line-height: 1.7;
 }

 .erp-message__icon {
 display: grid;
 width: 1.35rem;
 height: 1.35rem;
 flex: 0 0 1.35rem;
 place-items: center;
 border-radius: 50%;
 color: white;
 font-size: .7rem;
 font-weight: 800;
 }

 .erp-message--error .erp-message__icon {
 background: rgb(220 38 38);
 }

 .erp-message--warning .erp-message__icon {
 background: rgb(217 119 6);
 }

 .erp-message--success .erp-message__icon {
 background: rgb(5 150 105);
 }

 .erp-message--info .erp-message__icon {
 background: rgb(37 99 235);
 }

 main form.erp-surface>section+section {
 border-top: 1px solid rgb(241 245 249);
 padding-top: 1.25rem;
 }

 main form.erp-surface>section>h2,
 main .erp-surface>h2 {
 color: rgb(15 23 42);
 font-weight: 700;
 letter-spacing: -.01em;
 }

 main form.erp-surface> :last-child:is(.border-t) {
 margin-top: 1.25rem;
 background: rgb(248 250 252 / .7);
 margin-inline: -1.25rem;
 margin-bottom: -1.25rem;
 padding: 1rem 1.25rem;
 }

 main .overflow-x-auto {
 scrollbar-width: thin;
 scrollbar-color: rgb(148 163 184) rgb(241 245 249);
 }

 main table {
 border-collapse: separate;
 border-spacing: 0;
 }

 main table thead th {
 position: relative;
 background: rgb(248 250 252);
 color: rgb(71 85 105);
 font-size: .72rem;
 font-weight: 700;
 letter-spacing: .01em;
 line-height: 1.45;
 white-space: nowrap;
 }

 main table tbody tr {
 transition: background-color .12s ease, box-shadow .12s ease;
 }

 main table tbody tr:hover {
 background: rgb(239 246 255 / .68);
 box-shadow: inset -3px 0 0 rgb(59 130 246);
 }

 main table tbody td {
 color: rgb(51 65 85);
 vertical-align: middle;
 font-size: .8125rem;
 }

 main table :where(td,
 th)[dir="ltr"],
 main table :where(.tabular-nums) {
 text-align: left;
 font-feature-settings: "ss01", "tnum";
 font-variant-numeric: tabular-nums;
 }

 :where(code,
 kbd,
 samp,
 [dir="ltr"]) {
 direction: ltr;
 unicode-bidi: isolate;
 }

 main :where(button,
 a)[class*="bg-blue-600"] {
 transition: background-color .15s ease, box-shadow .15s ease;
 }

 main :where(button,
 input,
 select,
 textarea):disabled {
 cursor: not-allowed;
 opacity: .68;
 }

 main [aria-busy="true"] {
 cursor: progress;
 opacity: .72;
 }

 main .erp-surface> :where(.p-12,
 .py-16):where(.text-center) {
 min-height: 11rem;
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 background: linear-gradient(180deg, white, rgb(248 250 252 / .75));
 color: rgb(100 116 139);
 }

 @media (max-width: 639px) {
 .erp-page-header {
 align-items: stretch;
 flex-direction: column;
 }
 .erp-page-header__action {
 width: 100%;
 }
 main form.erp-surface> :last-child:is(.border-t) {
 flex-direction: column-reverse;
 align-items: stretch;
 }
 main form.erp-surface> :last-child:is(.border-t) :where(a,
 button) {
 width: 100%;
 text-align: center;
 }
 }

 .erp-mobile-nav>summary::-webkit-details-marker {
 display: none;
 }

 .erp-mobile-nav__backdrop {
 display: none;
 position: fixed;
 inset: 3.75rem 0 0;
 z-index: 40;
 cursor: default;
 background: rgb(15 23 42 / .55);
 }

 .erp-mobile-nav__panel {
 display: none;
 position: fixed;
 top: 3.75rem;
 right: 0;
 bottom: 0;
 z-index: 50;
 width: min(20rem, 88vw);
 overflow-y: auto;
 border-left: 1px solid var(--erp-sidebar-border);
 background: var(--erp-sidebar);
 padding: 1rem .75rem;
 box-shadow: -20px 0 30px rgb(15 23 42 / .18);
 }

 .erp-mobile-nav[open] :where(.erp-mobile-nav__backdrop,
 .erp-mobile-nav__panel) {
 display: block;
 }

 @media (prefers-reduced-motion: reduce) {
 *,
 *::before,
 *::after {
 scroll-behavior: auto !important;
 transition-duration: .01ms !important;
 }
 }
 </style>

